/*
 * A218347  Numbers of the form a^a + b^b, a>=b>=0.
 * https://oeis.org/A218347
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 27, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   big_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) is the n‑th smallest integer that can be expressed
 * as a^a + b^b with a ≥ b ≥ 0.  0^0 is defined to be 0.
 *
 * The sequence is generated by iterating over increasing a and b,
 * so the values are produced in strictly increasing order.
 */

#include <stdint.h>
#include <stdbool.h>
#include "../utils/big_pow.h"

seq_t a(idx_t n)
{
    if (n == 0) return 0;   /* undefined for n=0, but guard for safety */

    idx_t count = 0;        /* position in the sequence (1‑based) */

    for (idx_t a_val = 0; ; ++a_val) {
        /* compute a^a, with 0^0 defined as 0 */
        seq_t a_pow = (a_val == 0) ? 0 : big_pow((seq_t)a_val, (seq_t)a_val);

        for (idx_t b_val = 0; b_val <= a_val; ++b_val) {
            /* compute b^b, with 0^0 defined as 0 */
            seq_t b_pow = (b_val == 0) ? 0 : big_pow((seq_t)b_val, (seq_t)b_val);

            /* a^a + b^b is the next term in the sequence */
            seq_t val = a_pow + b_pow;
            ++count;

            if (count == n) return val;
        }
    }
}
